async function getProviderEntity(user) {
  const db = await getDb();
  if (!db) return null;
  if (user.email) {
    const byEmail = (await db.select().from(platformEntities).where(eq3(platformEntities.email, user.email.trim().toLowerCase())).limit(1))[0];
    if (byEmail) return byEmail;
  }
  const merchantRestaurantId = await getMerchantRestaurantId(user.id);
  if (!merchantRestaurantId) return null;
  const members = await db.select({ email: users.email }).from(users).innerJoin(restaurants, eq3(restaurants.id, merchantRestaurantId)).where(eq3(users.id, user.id)).limit(1);
  const memberEmail = members[0]?.email;
  if (memberEmail) {
    const byMember = (await db.select().from(platformEntities).where(eq3(platformEntities.email, memberEmail.trim().toLowerCase())).limit(1))[0];
    if (byMember) return byMember;
  }
  return null;
}
